    "stem": "A 34-year-old man is admitted to the general medicine teaching ward at Post Graduate Institute of Medical Education and Research (PGIMER) Chandigarh with clinical findings indicative of Acute Bronchiolitis in Infants Wheezing Supportive Hydration and Humidified Oxygen. Clinical examination and investigative review confirm avoiding unnecessary salbutamol, steroids, or antibiotics in respiratory syncytial virus infection. Vitals reveal blood pressure of 139/75 mm Hg, heart rate of 87/min, respiratory rate of 17/min, and temperature of 36.9C (98.3F). Diagnostic serum testing, focused physiological assessment, and targeted structural evaluations demonstrate characteristic pathophysiological hallmarks of acute bronchiolitis in infants wheezing supportive hydration and humidified oxygen. Which of the following is the most appropriate next step in clinical management according to Indian national guidelines?",
    "options": [
      {
        "text": "High-dose oral corticosteroid monotherapy without source control",
        "correct": false,
        "explanation": "Incorrect: Systemic corticosteroids without addressing the underlying infectious or structural etiology fail to alter disease progression."
      },
      {
        "text": "Intravenous loop diuretic administration in a hypovolemic or hypotensive patient",
        "correct": false,
        "explanation": "Incorrect: Administering potent loop diuretics during hypoperfusion exacerbates circulatory collapse and accelerates ischemic tubular injury."
      },
      {
        "text": "Avoiding unnecessary salbutamol, steroids, or antibiotics in respiratory syncytial virus infection",
        "correct": true,
        "explanation": "Correct: According to established evidence-based consensus and clinical practice guidelines, the primary indicated management for this clinical scenario is avoiding unnecessary salbutamol, steroids, or antibiotics in respiratory syncytial virus infection. This directly addresses the underlying pathophysiological abnormality, optimizes therapeutic outcomes, and mitigates disease-specific morbidity."
      },
      {
        "text": "Intensive intravenous insulin bolus therapy without baseline potassium evaluation",
        "correct": false,
        "explanation": "Incorrect: Rapid insulin infusion shifts extracellular potassium intracellularly, precipitating lethal hypokalemia-induced cardiac arrest."
      },
      {
        "text": "Intravenous sodium bicarbonate push in mild diabetic ketoacidosis",
        "correct": false,
        "explanation": "Incorrect: Alkalinization therapy in DKA with arterial pH > 6.9 provides no clinical benefit and precipitates paradoxical CSF acidosis and hypokalemia."
      }
    ],
    "explanation": "Educational Objective: Understand the diagnosis, guideline-directed management, and clinical rationale for Acute Bronchiolitis in Infants Wheezing Supportive Hydration and Humidified Oxygen.\\n\\nClinical Discussion: This clinical presentation corresponds to Acute Bronchiolitis in Infants Wheezing Supportive Hydration and Humidified Oxygen. The cornerstone of management involves avoiding unnecessary salbutamol, steroids, or antibiotics in respiratory syncytial virus infection. Clinical decision-making prioritizes rapid diagnosis, stabilization, and adherence to established clinical guidelines. Alternative choices represent suboptimal management strategies, delayed interventions, or therapies lacking efficacy in this specific clinical presentation.",
